const item = $input.first().json;

// Gmail Trigger v1.4 returns capitalised header fields: From, Subject, To
// Try every known shape so this works across node versions.
let rawFrom = item.From || item.from || '';

// Some versions nest headers under payload.headers
if (!rawFrom && item.payload && Array.isArray(item.payload.headers)) {
  const h = item.payload.headers.find(x => String(x.name).toLowerCase() === 'from');
  if (h) rawFrom = h.value;
}

let fromEmail = '';
if (rawFrom && typeof rawFrom === 'object' && rawFrom.address) {
  fromEmail = rawFrom.address;
} else if (typeof rawFrom === 'string') {
  const match = rawFrom.match(/<([^>]+)>/);
  fromEmail = match ? match[1] : rawFrom;
}
fromEmail = String(fromEmail).trim().toLowerCase();

let subject = item.Subject || item.subject || '';
if (!subject && item.payload && Array.isArray(item.payload.headers)) {
  const h = item.payload.headers.find(x => String(x.name).toLowerCase() === 'subject');
  if (h) subject = h.value;
}
subject = String(subject || 'No Subject').trim();

const bodyText = String(item.text || item.textPlain || item.snippet || item.body || '').trim();
const messageId = item.id || item.messageId || ('msg_' + Date.now());
const threadId = item.threadId || messageId;

if (!fromEmail) {
  throw new Error('Could not extract sender email from Gmail trigger payload. Keys seen: ' + Object.keys(item).join(', '));
}

return [{
  json: {
    fromEmail,
    subject,
    bodyText,
    messageId,
    threadId,
    rawFrom: String(rawFrom)
  }
}];

const meta = $('Extract Email Metadata').item.json;
const profile = $('Lookup Profile by Email').item.json;
const holdersRecords = $input.all();

const authorizedAccounts = [];
holdersRecords.forEach(rec => {
  if (rec.json && rec.json.accounts) {
    authorizedAccounts.push({
      account_id: rec.json.accounts.id,
      account_number: rec.json.accounts.account_number,
      account_type: rec.json.accounts.account_type,
      currency: rec.json.accounts.currency,
      balance: rec.json.accounts.balance,
      status: rec.json.accounts.status,
      role: rec.json.role
    });
  }
});

const rawText = (meta.subject || '') + ' ' + (meta.bodyText || '');
const text = rawText.toLowerCase();

let intent = 'UNKNOWN';
let transferDetails = null;

const wantsTransfer = /\b(transfer|send|pay|remit|wire)\b/.test(text);
const wantsBalance = /\b(balance|how much|statement|summary)\b/.test(text);
const wantsPolicy = /\b(policy|policies|fee|fees|limit|limits|overdraft|credit card|interest rate|rule|rules|terms)\b/.test(text);
const wantsStanding = /\b(standing order|recurring|scheduled payment|direct debit)\b/.test(text);
const wantsDispute = /\b(dispute|fraud|unauthorized|unauthorised|stolen|freeze|chargeback|didn't make|did not make|don't recognize|do not recognize)\b/.test(text);
const wantsOpen = /\b(open an account|open account|new account|sign up|become a customer)\b/.test(text);

// Order matters: most specific first.
if (wantsOpen) {
  intent = 'OPEN_ACCOUNT';
} else if (wantsDispute) {
  intent = 'DISPUTE';
} else if (wantsStanding) {
  intent = 'STANDING_ORDER';
} else if (wantsTransfer) {
  intent = 'TRANSFER';

  // MONEY UNITS: the database stores BIGINT minor units (cents).
  // Customers write major units ("7000" = 7000.00). Always multiply by 100.
  // Never guess based on magnitude.
  let amountMinor = 0;
  const amtMatch = rawText.match(/(\d[\d,]*(?:\.\d{1,2})?)/);
  if (amtMatch) {
    const major = parseFloat(amtMatch[1].replace(/,/g, ''));
    if (!isNaN(major) && major > 0) {
      amountMinor = Math.round(major * 100);
    }
  }

  let destAccount = null;
  const acctMatch = meta.bodyText.match(/\b(TEST-[A-Z0-9-]+)\b/i);
  if (acctMatch) {
    destAccount = acctMatch[1].toUpperCase();
  } else {
    const uuidMatch = meta.bodyText.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
    if (uuidMatch) destAccount = uuidMatch[0];
  }

  const primaryAcc = authorizedAccounts.find(a => a.role === 'primary' && a.status === 'active') || authorizedAccounts.find(a => a.status === 'active') || null;

  transferDetails = {
    source_account_id: primaryAcc ? primaryAcc.account_id : null,
    destination_account: destAccount,
    amount: amountMinor,
    currency: primaryAcc ? primaryAcc.currency : 'USD',
    idempotency_key: 'gmail_' + meta.messageId
  };
} else if (wantsBalance) {
  intent = 'BALANCE';
} else if (wantsPolicy) {
  intent = 'POLICY_RAG';
}

// PRIVACY: deny any attempt to read an account the sender does not hold.
const ownNumbers = authorizedAccounts.map(a => String(a.account_number).toUpperCase());
const mentioned = rawText.toUpperCase().match(/\bTEST-[A-Z0-9-]+\b/g) || [];
const foreignMentioned = mentioned.filter(n => ownNumbers.indexOf(n) === -1);

if ((intent === 'BALANCE' || intent === 'UNKNOWN') && foreignMentioned.length > 0) {
  intent = 'UNAUTHORIZED_ACCESS';
}

return [{
  json: {
    fromEmail: meta.fromEmail,
    subject: meta.subject,
    bodyText: meta.bodyText,
    messageId: meta.messageId,
    profile_id: profile.id,
    full_name: profile.full_name,
    authorizedAccounts,
    intent,
    transferDetails
  }
}];

const item = $input.first().json;
const accounts = item.authorizedAccounts || [];

let balanceMsg = `Hello ${item.full_name},

Here is your authorized account balance summary:

`;

if (accounts.length === 0) {
  balanceMsg += "No active accounts found for your profile.";
} else {
  accounts.forEach(acc => {
    const formatted = (acc.balance / 100).toFixed(2);
    balanceMsg += `- Account ${acc.account_number} (${acc.account_type.toUpperCase()}, Role: ${acc.role}): $${formatted} ${acc.currency} (Status: ${acc.status})
`;
  });
}

balanceMsg += `
Thank you for banking with Digital Bank.`;

return [{ json: { fromEmail: item.fromEmail, subject: item.subject, message: balanceMsg, profile_id: item.profile_id } }];

