const ctx = $('Classify Intent & Authorize Request').item.json;
const td = ctx.transferDetails || {};
const authorized = ctx.authorizedAccounts || [];

// AUTHORIZATION: source must be an account this sender actually holds.
const source = authorized.find(a => a.account_id === td.source_account_id && a.status === 'active');

if (!source) {
  return [{ json: {
    ok: false,
    reason: 'You do not have an active account authorized for outgoing transfers.',
    fromEmail: ctx.fromEmail, subject: ctx.subject, full_name: ctx.full_name
  } }];
}

if (!td.destination_account) {
  return [{ json: {
    ok: false,
    reason: 'We could not identify the destination account. Please include the destination account number, for example: "Send 5000 to account TEST-BOB-001".',
    fromEmail: ctx.fromEmail, subject: ctx.subject, full_name: ctx.full_name
  } }];
}

if (!td.amount || td.amount <= 0) {
  return [{ json: {
    ok: false,
    reason: 'We could not identify a valid transfer amount. Please state the amount clearly.',
    fromEmail: ctx.fromEmail, subject: ctx.subject, full_name: ctx.full_name
  } }];
}

return [{ json: {
  ok: true,
  source_account_id: source.account_id,
  source_account_number: source.account_number,
  source_currency: source.currency,
  destination_lookup: td.destination_account,
  amount: td.amount,
  idempotency_key: td.idempotency_key,
  initiated_by_profile_id: ctx.profile_id,
  fromEmail: ctx.fromEmail, subject: ctx.subject, full_name: ctx.full_name
} }];
